else {$parent=realpath(dirname(ROOT));$public=realpath($_SERVER['DOCUMENT_ROOT']??ROOT);if($parent===$public||str_starts_with($parent,$public.DIRECTORY_SEPARATOR))throw new InvalidArgumentException('SQLite exige armazenamento fora da pasta pública. Nesta instalação em subpasta, use MySQL.');$dir=dirname(ROOT).'/.s7ven-private-'.bin2hex(random_bytes(10));if(!mkdir($dir,0700,true))throw new RuntimeException('Não foi possível criar pasta privada SQLite fora da pasta do site. Use MySQL.');$cfg['path']=$dir.'/database.sqlite';$p=new PDO('sqlite:'.$cfg['path'],null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
